import {
  AssigneesSection,
  type CopilotAssignmentModalConfig,
} from '@github-ui/security-products-alert-assignees/components/AssigneesSection'
import type {Assignee, DependabotAlertAssigneesRepository} from './types'
import {dependabotAlertAssigneesPath, dependabotAvailableAssigneesPath} from '@github-ui/paths'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {useMemo, useCallback} from 'react'

export interface DependabotAlertAssigneesSectionProps {
  alertNumber: number
  repository: DependabotAlertAssigneesRepository
  currentUser: Assignee
  assignees: Assignee[]
  readonly: boolean
  assignableToCopilot?: boolean
  useCopilotAssignmentModal?: boolean
}

// When we migrate this timeline event to React, we can remove this refresh:
// https://github.com/github/dependabot-updates/issues/12339
function refreshPage() {
  window.location.reload()
}

export function DependabotAlertAssigneesSection({
  alertNumber,
  repository,
  currentUser,
  assignees,
  readonly,
  assignableToCopilot,
  useCopilotAssignmentModal,
}: DependabotAlertAssigneesSectionProps) {
  const onSubmit = useCallback(
    async (
      _graphQLId: string,
      selectedBranch?: string,
      content?: string,
      selectedAgent?: {topLevelAgentId?: string; subAgentSlug?: string},
      selectedModel?: string,
      selectedRepoNwo?: string,
    ) => {
      const resp = await verifiedFetchJSON(
        `/${repository.ownerLogin}/${repository.name}/security/dependabot/${alertNumber}/agent_assignments`,
        {
          method: 'POST',
          body: {
            repo_name_with_owner: selectedRepoNwo,
            base_ref: selectedBranch,
            custom_instructions: content,
            custom_agent: selectedAgent?.subAgentSlug,
            agent_id: selectedAgent?.topLevelAgentId,
            model: selectedModel,
          },
        },
      )
      if (!resp.ok) throw new Error('Failed to assign Copilot')
    },
    [repository.ownerLogin, repository.name, alertNumber],
  )

  const copilotAssignmentModal: CopilotAssignmentModalConfig | undefined = useMemo(
    () =>
      useCopilotAssignmentModal
        ? {
            repository: {name: repository.name, owner: {login: repository.ownerLogin}},
            alertNumbers: [alertNumber],
            onAssignmentComplete: refreshPage,
            onSubmit,
            title: 'Assign agent to alert',
            description:
              'The agent will analyze this vulnerability and open a draft pull request with a proposed fix, including updating the dependency and resolving any breaking changes introduced by the update.',
          }
        : undefined,
    [useCopilotAssignmentModal, repository.name, repository.ownerLogin, alertNumber, onSubmit],
  )

  return (
    <div style={{marginInline: 'calc(var(--base-size-8) * -1)'}}>
      <AssigneesSection
        availableAssigneesPath={dependabotAvailableAssigneesPath({owner: repository.ownerLogin, repo: repository.name})}
        updateAssigneesPath={dependabotAlertAssigneesPath({
          owner: repository.ownerLogin,
          repo: repository.name,
          alertNumber,
        })}
        currentUser={currentUser}
        assignees={assignees}
        readonly={readonly}
        assignableToCopilot={assignableToCopilot}
        copilotAssignmentModal={copilotAssignmentModal}
        showAssignToAgentButton={!!useCopilotAssignmentModal}
        onAssignmentChange={refreshPage}
      />
    </div>
  )
}
